                  "Ref": "AWS::Region"
                },
                "RootDeviceName"
              ]
            },
            "Ebs": {
              "VolumeSize": 24
            }
          }
        ]
      }
    },
    "ChromaInstanceSecurityGroup": {
      "Type": "AWS::EC2::SecurityGroup",
      "Properties": {
        "GroupDescription": "Chroma Instance Security Group",
        "SecurityGroupIngress": [
          {
            "IpProtocol": "tcp",
